/// Status codes for MediaPipe C API functions.
/// These codes are aligned with absl::StatusCode.
enum MpStatus {
  kMpOk(0),
  kMpCancelled(1),
  kMpUnknown(2),
  kMpInvalidArgument(3),
  kMpDeadlineExceeded(4),
  kMpNotFound(5),
  kMpAlreadyExists(6),
  kMpPermissionDenied(7),
  kMpResourceExhausted(8),
  kMpFailedPrecondition(9),
  kMpAborted(10),
  kMpOutOfRange(11),
  kMpUnimplemented(12),
  kMpInternal(13),
  kMpUnavailable(14),
  kMpDataLoss(15),
  kMpUnauthenticated(16);

  final int value;
  const MpStatus(this.value);

  static MpStatus fromValue(int value) => switch (value) {
    0 => kMpOk,
    1 => kMpCancelled,
    2 => kMpUnknown,
    3 => kMpInvalidArgument,
    4 => kMpDeadlineExceeded,
    5 => kMpNotFound,
    6 => kMpAlreadyExists,
    7 => kMpPermissionDenied,
    8 => kMpResourceExhausted,
    9 => kMpFailedPrecondition,
    10 => kMpAborted,
    11 => kMpOutOfRange,
    12 => kMpUnimplemented,
    13 => kMpInternal,
    14 => kMpUnavailable,
    15 => kMpDataLoss,
    16 => kMpUnauthenticated,
    _ => throw ArgumentError('Unknown value for MpStatus: $value'),
  };
}

