  MpTextEmbedderRole get role => MpTextEmbedderRole.fromValue(roleAsInt);
  set role(MpTextEmbedderRole value) => roleAsInt = value.value;

  static ffi.Pointer<MpTextEmbedderFormatContext> $allocate(
    ffi.Allocator $allocator, {
    required MpTextEmbedderEmbeddingType task_type,
    required ffi.Pointer<ffi.Char> title,
    required MpTextEmbedderRole role,
  }) => $allocator<MpTextEmbedderFormatContext>()
    ..ref.task_type = task_type
    ..ref.title = title
    ..ref.role = role;
}

